  "혼자 플레이는 {0}. 난이도 하(×1), 중(좌표 없음, ×2), 상(좌표 없음 + 흑 시점, ×3), 기록은 맞힌 개수 × 배율": "El modo en solitario es una {0}. Dificultad Baja (×1), Media (sin coordenadas, ×2), Alta (sin coordenadas + vista de las negras, ×3); tu marca son los aciertos × el multiplicador",
