  "상점": "Tienda",
  "보유 중인 OC 나이트 코인": "Monedas OC Caballo que tienes",
  "궁금한 점": "¿Tienes dudas?",
  "무료 여부": "¿Es gratis?",
  "오프닝 학습·엔진 분석·오프닝 도감·퍼즐 등 핵심 기능 모두 무료": "Todas las funciones principales, como el estudio de aperturas, el análisis con motor, el libro de aperturas y los puzles, son gratuitas",
  "회원가입 없이 이용": "Úsalo sin registrarte",
  "게스트로도 대부분의 화면 이용 가능. 진도(도감 해금)·해결한 퍼즐·친구·실시간 대국처럼 계정에 저장되는 기능은 로그인 필요": "La mayoría de las pantallas funcionan como invitado. Las funciones que se guardan en tu cuenta, como el progreso (aperturas desbloqueadas), los puzles resueltos, los amigos y las partidas en tiempo real, requieren iniciar sesión",
  "학습, 도감": "Aprendizaje y aperturas",
  "학습 탭 기능": "Qué hace la pestaña Aprender",
  "체스판을 직접 두거나 PGN·FEN·chess.com 대국을 불러와 엔진 분석. 매 수의 정확도(최선/우수/실수/블런더 등급) 표시": "Juega tú mismo en el tablero o carga un PGN, un FEN o una partida de chess.com para analizarla con el motor. La precisión de cada jugada se muestra como una calificación (Mejor, Excelente, Error, Error grave, etc.)",
  "오프닝 도감이란": "¿Qué es el libro de aperturas?",
  "체스 오프닝을 트리 구조로 정리한 지도. 학습 탭에서 오프닝을 실제로 두면 그 갈래가 도감에 해금, 도감에서 각 오프닝의 정통 수순과 유래 확인": "Un mapa de las aperturas de ajedrez organizado como un árbol. Al jugar de verdad una apertura en la pestaña Aprender, esa rama se desbloquea en el libro, donde puedes ver las jugadas estándar y el origen de cada apertura",
  "사용하는 엔진": "Qué motor se usa",
  "Stockfish 계열 엔진 사용. 설정 탭에서 가볍고 빠른 기본 엔진, 더 강력한 Stockfish 17.1, 18 중 선택": "Se usa un motor de la familia Stockfish. En Ajustes puedes elegir entre el motor predeterminado, ligero y rápido, y el más potente Stockfish 17.1 o 18",
  "퍼즐 생성 방식": "Cómo se crean los puzles",
  "퍼즐 탭의 \"퍼즐 만들기\"에서 PGN·FEN 입력 또는 내 chess.com 대국 선택. 그 안의 실제 수(기물 희생·우위 점하기·실수 응징하기 등)로 직접 제작": "En «Crear puzles» de la pestaña Puzles, introduce un PGN o un FEN o elige una de tus partidas de chess.com. Creas un puzle con las jugadas reales de esa partida (sacrificar una pieza, obtener ventaja, castigar un error, etc.)",
  "퍼즐 비공개 설정": "Hacer privado un puzle",
  "퍼즐 만들기 마지막 단계 또는 이미 만든 퍼즐의 풀이 카드에서 언제든 공개/비공개 변경": "Cambia entre pública y privada en el último paso de la creación o en cualquier momento desde la tarjeta de un puzle que ya hayas creado",
  "다른 사람의 퍼즐 풀기": "Resolver los puzles de otras personas",
  "공개 퍼즐은 퍼즐 탭 목록에서 누구나 풀 수 있고, 좋아요·리포스트·공유 가능": "Cualquiera puede resolver los puzles públicos desde la lista de la pestaña Puzles, y darles me gusta, compartirlos de nuevo o enviarlos",
  "PLAY 페이지에서 타임 컨트롤을 고른 뒤 \"대국 상대 찾기\"로 랜덤 매칭, 또는 \"친구와 플레이하기\"에서 친구에게 도전장 발송": "En la página PLAY, elige un control de tiempo y usa «Buscar rival» para un emparejamiento aleatorio, o envía un reto a un amigo desde «Jugar con un amigo»",
  "채팅에서 대국 신청": "Retar desde el chat",
  "친구와의 채팅창에 /play 명령어 입력. 예: \"/play 10\"은 10분 대국, \"/play 15+10\"은 15분에 매 수마다 10초씩 증가. 상대가 수락하면 바로 대국 시작": "Escribe el comando /play en el chat con un amigo. Por ejemplo, «/play 10» es una partida de 10 minutos y «/play 15+10» son 15 minutos con 10 segundos de incremento por jugada. La partida empieza en cuanto lo acepte",
  "매칭 대기 중 페이지 이탈": "Salir de la página mientras esperas un emparejamiento",
  "대기열에 있었다면 매칭 자동 취소, 진행 중인 대국이었다면 기권 처리": "Si estabas en la cola, el emparejamiento se cancela automáticamente; si había una partida en curso, cuenta como abandono",
  "계정, 데이터": "Cuenta y datos",
  "소셜 로그인 (Google, Apple, Facebook)": "Inicio de sesión social (Google, Apple, Facebook)",
  "로그인 창에서 바로 선택 가능. 로그인 후 \"계정 센터\"에서 여러 로그인 수단을 하나의 계정에 연결하면 어떤 수단으로든 같은 계정으로 로그인": "Elige uno directamente en la ventana de inicio de sesión. Tras iniciar sesión, vincula varios métodos a una sola cuenta en el «Centro de cuenta» y cualquiera de ellos te dará acceso a la misma cuenta",
  "계정 탈퇴 시 데이터": "Tus datos al eliminar la cuenta",
  "다른 기기에서 진도 이어가기": "Continuar tu progreso en otro dispositivo",
  "로그인하면 어느 기기에서든 같은 진도(도감 해금·해결한 퍼즐·XP 등) 이용": "Al iniciar sesión tienes el mismo progreso (aperturas desbloqueadas, puzles resueltos, XP, etc.) en cualquier dispositivo",
  "버그 제보": "Informar de un error",
  "설정 탭의 \"문의 / FAQ\" 카드에서 이메일로 제보. 화면이 어디서 어떻게 달랐는지 함께 적으면 빠르게 확인": "Infórmalo por correo desde la tarjeta «Contacto / FAQ» de Ajustes. Si indicas dónde y cómo se veía distinta la pantalla, lo comprobamos más rápido",
  "시작하기 {0}": "Empezar {0}",
  "자주 묻는 질문": "Preguntas frecuentes",
  "막히는 부분은 여기서 먼저 확인. 답이 없으면 맨 아래에서 문의": "Si te atascas, mira primero aquí. Si no encuentras la respuesta, escríbenos al final de la página",
  "원하는 답이 없나요?": "¿No encuentras tu respuesta?",
  "문제나 궁금한 점을 이메일로 보내면 확인 후 답변": "Envíanos tu problema o duda por correo y te responderemos tras comprobarlo",
  "{0} 이메일로 문의하기": "{0} Contáctanos por correo",
  "{0} OpenChess로 돌아가기": "{0} Volver a OpenChess",
