  "{0}년생": "Nacido en {0}",
  "마스터 대국 DB 선수": "Jugadores de la base de maestros",
  "FIDE 스탠다드 랭킹": "Ranking FIDE clásico",
  "FIDE 래피드 랭킹": "Ranking FIDE rápido",
  "FIDE 블리츠 랭킹": "Ranking FIDE blitz",
  "대진표": "Cuadro",
  "마스터 대국 DB에 이 연도 대국 없음": "No hay partidas de este año en la base de partidas de maestros",
  "앱스토어 출시 준비 추가했습니다. 로그인을 시스템 브라우저로 처리하고 앱 링크로 돌아오도록 연결, 체스 엔진은 필요할 때 내려받도록 변경했습니다.": "Preparación para las tiendas de apps: el inicio de sesión usa el navegador del sistema y vuelve mediante enlaces de la app; el motor de ajedrez se descarga cuando hace falta.",
  "모든 수의 등급(탁월·최선·실수 등)을 보드 위 효과로 표시합니다. 설정에서 모두, 탁월/유일만, 끔 중에서 선택했습니다.": "Cada calificación de jugada (brillante, mejor, error, etc.) se muestra como efecto en el tablero. En ajustes: Todas, solo Brillante/Única o Desactivado.",
  "도감에 '마스터' 탭 추가했습니다. 세계 챔피언 계보와 대회(우승자·마스터 대국 DB 집계·대표 대국), 회로도 모양의 마스터 트리, FIDE 스탠다드·래피드·블리츠 상위 100위 랭킹, 대국 DB 최고 레이팅 상위 900명 마스터 추가했습니다.": "Se añade la pestaña 'Maestros' al dex: linaje de campeones del mundo, torneos (ganadores, recuento de la base de partidas, partidas destacadas), un árbol de maestros en forma de circuito, el top 100 FIDE en Estándar, Rápidas y Blitz, y los 900 mejores maestros de la base por Elo máximo.",
  "마스터 이름을 한글로 표기하고 국적을 국기 이모지로 표시합니다. 최고 레이팅 알약 왼쪽에 MAX 표시합니다.": "Los nombres de los maestros se muestran en coreano y las nacionalidades con emoji de bandera. Una etiqueta MAX aparece a la izquierda de la píldora de Elo máximo.",
  "'외부로 공유' 화면을 모든 곳에서 같은 모양으로 통일했습니다.": "Se unifica la pantalla 'Compartir fuera' para que se vea igual en todas partes.",
  "플레이 탭의 미니게임 이름·레이팅 배치를 정리하고, 일반 대국 카드에 레이팅 줄(배치를 마친 분류만)과 타임 컨트롤 분류별 레이팅 알약 추가했습니다. 상단의 '내 기록·래피드' 제목 삭제했습니다.": "Se ordena la disposición de nombre y Elo de los minijuegos en la pestaña Jugar, y la tarjeta de partida normal añade una fila de Elo (solo categorías con clasificación) y píldoras de Elo por control de tiempo. Se elimina el título 'Mi historial, Rápidas' de arriba.",
  "오프닝 트리의 보이는 영역과 드래그 감도를 마스터 트리와 같게 통일하고, 마스터 트리에 확대·축소(100% 기준)와 모바일 두 손가락 확대 추가했습니다.": "El área visible y la sensibilidad de arrastre del árbol de aperturas ahora coinciden con las del árbol de maestros, que además suma zoom (base 100 %) y zoom con dos dedos en móvil.",
  "마스터 트리의 챔피언·랭킹·마스터 블록 디자인을 새로 다듬고 고급 서체로 교체했습니다. 가운데 칩에서 사방으로 전류가 흐르는 효과 추가했습니다.": "Se rediseñan los bloques de campeones, clasificación y maestros del árbol con tipografías premium, y se añade un efecto de corriente eléctrica que fluye desde el chip central en las cuatro direcciones.",
  "탁월한 수 판정이 체크메이트가 걸린 상황에서 독이 든 희생을 통과시키던 문제를 수정했습니다.": "Se corrige la detección de jugadas brillantes que dejaba pasar sacrificios envenenados en posiciones con jaque mate.",
  "모바일에서 마스터 상세 카드가 잘려 보이던 문제를 수정했습니다.": "Se corrige que la tarjeta de detalle del maestro apareciera recortada en móvil.",
  "마스터 도감, 수 등급 보드 효과, 앱스토어 출시 준비, 탁월한 수 판정 보정했습니다.": "Dex de maestros, efectos de calificación, preparación para tiendas, corrección de jugadas brillantes.",
  "마스터 도감, FIDE 상위 100위, 수 등급 효과, 앱스토어 준비 추가했습니다.": "Dex de maestros, top 100 FIDE, efectos de calificación, preparación para tiendas",
  "마스터 도감, FIDE 상위 100위, 수 등급 효과, 앱스토어 준비": "Dex de maestros, top 100 FIDE, efectos de calificación, preparación para tiendas",
  "계정 및 데이터 삭제 안내": "Eliminación de cuenta y datos",
  "1. 앱·웹에서 직접 삭제": "1. Elimínala tú mismo en la app o en la web",
  "OpenChess에 로그인한 뒤 설정 탭에서 계정 센터 열기": "Inicia sesión en OpenChess y abre el Centro de cuenta desde la pestaña Ajustes",
  "계정 센터 아래쪽의 \"계정 탈퇴\"를 누르고 아이디를 입력해 확인": "Pulsa \"Eliminar cuenta\" al final del Centro de cuenta y escribe tu nombre de usuario para confirmar",
  "2. 삭제되는 데이터": "2. Datos que se eliminan",
  "계정 정보(이메일, 로그인 수단 연결, 아이디, 닉네임, 회원 번호)와 프로필 사진·소개": "Información de la cuenta (correo, métodos de acceso vinculados, nombre de usuario, apodo, número de miembro) y tu foto de perfil y descripción",
  "학습 진도, 퍼즐 풀이 기록과 직접 만든 퍼즐, 대국·미니게임 기록과 레이팅": "Progreso de aprendizaje, historial de problemas resueltos y problemas que creaste, registros de partidas y minijuegos, y Rating",
  "친구 관계, 채팅 메시지, 알림, 신고·차단 내역": "Relaciones de amistad, mensajes de chat, notificaciones e historial de denuncias y bloqueos",
  "진행 중이던 대국은 기권 처리되어 상대에게 승리로 기록된 뒤 삭제": "Las partidas en curso se abandonan, se registran como victoria de tu rival y después se eliminan",
  "3. 삭제 후에도 남는 정보": "3. Información que permanece tras la eliminación",
  "상대의 통계에 이미 반영된 승패·레이팅 변동 수치는 남지만 탈퇴한 이용자를 알아볼 수 없음": "Las victorias, derrotas y cambios de Rating ya aplicados a las estadísticas de tu rival permanecen, pero no se puede identificar al usuario eliminado",
  "4. 로그인할 수 없는 경우": "4. Si no puedes iniciar sesión",
  "가입한 이메일 주소에서 {0}로 \"계정 삭제 요청\"과 아이디(또는 회원 번호)를 보내기": "Envía \"Solicitud de eliminación de cuenta\" y tu nombre de usuario (o número de miembro) a {0} desde el correo con el que te registraste",
  "본인 확인 후 삭제하고 처리 결과를 회신": "Eliminamos la cuenta tras verificar tu identidad y te respondemos con el resultado",
  "5. 문의처": "5. Contacto",
