  "아직 분석된 실수가 없음": "Aún no hay errores analizados",
  "게임 리뷰를 열면 내가 둔 실수·블런더·놓친 수가 자동으로 쌓이고, 여기에 약점 지도가 그려짐": "Abre una revisión de partida y los errores, blunders y jugadas perdidas que cometiste se reúnen automáticamente; aquí se dibuja tu mapa de debilidades",
