  "내 대국을 리뷰하다가 최선·유일·탁월 수에서 유산으로 남기기를 누르면 게시물로 쌓임": "Revisa tus partidas y pulsa Guardar como legado en una jugada Mejor, Única o Brillante para añadir una publicación",
