  "내 쪽의 포크·핀·메이트 같은 전술이 있는지 먼저 훑어보기": "Buscar primero tácticas propias como horquillas, clavadas y mates",
  "리뷰하기": "Revisar",
  "리뷰한 {0}판 기준": "Basado en {0} partidas revisadas",
