  "수 유형별 분석": "Análisis por tipo de jugada",
  "수 종류별": "Por tipo de jugada",
  "수를 두기 전에 상대가 포크·핀 같은 전술을 걸 수 있는지 확인하기": "Antes de mover, comprobar si el rival puede aplicar una horquilla, clavada u otra táctica",
  "실수 {0}%": "Errores {0}%",
  "실수 원인 분석 중, {0}개 남음": "Analizando causas de errores, quedan {0}",
  "실수율": "Tasa de errores",
  "아직 두 판 이상에서 반복된 실수가 없음": "Aún no hay errores repetidos en dos o más partidas",
  "이 실수를 모두 없애면 평균 정확도 최대 약 +{0}%p": "Eliminar todos estos errores podría subir la precisión media hasta unos +{0}%p",
