  "강한 상대를 이긴 대표 대국": "Victorias destacadas ante rivales fuertes",
  "래피드·블리츠·온라인 대국이 섞여 있음.": "Incluye partidas Rapid, Blitz y en línea.",
  // (v0.6.5) 리뷰 코치(MEC) 문구
  "{0}에 있는 {1:을/를} 잃게 됩니다.": "{1} en {0} en riesgo de perderse",
  "{0}의 {1:을/를} 이대로 두면 잃게 됩니다.": "{1} en {0} se pierde si se deja",
  "지금대로면 {0}에 있는 {1:을/를} 잃습니다.": "A punto de perder {1} en {0}",
  "{0}에 있는 {1:이/가} 당장 위험하지만, 엔진에 의하면 문제없는 수입니다.": "{1} en {0} expuesto, pero el motor valora bien la jugada",
  "{0}의 {1:이/가} 위험을 안고 있지만, 엔진에 의하면 괜찮은 수입니다.": "Deja {1} en {0} en riesgo, pero el motor lo aprueba",
  "{0}의 {1:을/를} 잃을 수 있어도, 엔진에 의하면 좋은 수입니다.": "{1} en {0} podría perderse, pero el motor la valora bien",
  "이 수는 상대 {0:을/를} 위협합니다.": "Amenaza a {0} rival",
  "상대 {0:이/가} 이 수의 위협을 받고 있습니다.": "Amenaza, {0} rival bajo ataque",
  "이제 상대 {0:을/를} 위협하고 있습니다.": "Esta jugada crea una amenaza a {0} rival",
  "상대 {0:이/가} 걸려 있습니다. 잡을 기회입니다.": "Ocasión de capturar, {0} rival expuesto",
  "상대 {0:을/를} 잡을 수 있는 상황입니다.": "Se puede capturar {0} rival",
  "아직 상대 {0:이/가} 방치돼 있습니다. 놓치지 말아야 합니다.": "No lo pases por alto, {0} rival sin protección",
  "{0:을/를} 잡지 않았지만 여전히 좋은 수입니다.": "No capturó {0}, pero es buena jugada",
  "{0:을/를} 잡을 수도 있었지만, 이 수도 충분히 좋습니다.": "Podía capturar {0}, pero esta jugada también basta",
  "당장 {0:을/를} 안 잡아도 이 수면 충분합니다.": "No hace falta capturar {0} ahora",
  "상대 {0:을/를} 잡는 게 최선이었지만, 이 수도 여전히 좋습니다.": "Capturar {0} rival era lo mejor. Esta jugada también es buena",
  "사실 {0:을/를} 잡을 수 있었습니다. 그래도 이 수 역시 좋은 선택입니다.": "En realidad se podía capturar {0}. Esta también es buena elección",
  "{0:을/를} 잡는 게 최선이었으며, 다만 이 수도 나쁘지 않습니다.": "Capturar {0} era lo mejor, pero esta jugada tampoco es mala",
  "유리한 상황에서의 기물 교환은 게임을 쉽고 안정적으로 풀어가는 좋은 방법입니다.": "Con ventaja, cambiar piezas es una buena forma de simplificar",
  "이기고 있을 때 기물을 교환해 상황을 단순하게 만드는 좋은 선택입니다.": "Cambiar Piezas cuando vas por delante para simplificar la partida es una buena elección.",
  "유리할 때는 기물을 바꿔가며 안정적으로 승리를 굳히는 게 좋습니다.": "Con ventaja, cambia piezas para asegurar la victoria",
  "지고 있을 때는 기물 교환을 피하는 게 좋지만, 이 교환은 불가피한 최선의 선택이었습니다.": "Cuando vas por detrás conviene evitar cambiar Piezas, pero este cambio fue la mejor opción inevitable.",
  "기물 교환은 원래 피해야 하는 상황이지만, 이 교환만큼은 어쩔 수 없는 최선이었습니다.": "Normalmente habría que evitar cambiar Piezas, pero este cambio fue lo mejor que se podía hacer.",
  "지고 있는 상황에서도 이 교환은 최선으로 불가피했습니다.": "Aun con desventaja, este cambio es lo mejor",
  "지고 있을 때는 기물 교환을 피하는 게 좋지만, 이 교환은 좋은 선택이었습니다.": "Cuando vas por detrás conviene evitar cambiar Piezas, pero este cambio fue una buena elección.",
  "원래는 피해야 할 기물 교환이지만, 이번엔 괜찮은 선택이었습니다.": "Normalmente es un cambio de Piezas que conviene evitar, pero esta vez fue una elección aceptable.",
  "지고 있는 상황이라도 이 교환만큼은 나쁘지 않은 선택이었습니다.": "Aun con desventaja, este cambio no está mal",
  "유리한 상황이라도 목적 없는 기물 교환은 손해가 될 수 있습니다. 기물 교환은 목적을 갖고 해야 합니다.": "Aunque vayas ganando, cambiar Piezas sin un propósito puede salir caro, cambia Piezas con un objetivo.",
  "이기고 있어도 이 교환은 아쉬운 선택이었습니다. 기물 교환에는 목적이 있어야 합니다.": "Aunque ibas ganando, este cambio fue una pena, un cambio de Piezas necesita un propósito.",
  "유리한 상황을 단순화하려던 거라면, 이번 교환은 아쉬운 선택이었습니다.": "Si el cambio buscaba simplificar una posición ganadora, es una elección decepcionante",
  "지고 있는 상황에서는 기물 교환을 피하는 게 좋은데, 이 교환은 아쉬운 선택이었습니다. 기물 교환은 목적을 갖고 해야 합니다.": "Cuando vas por detrás es mejor evitar cambiar Piezas, y este cambio fue una pena, cambia Piezas con un objetivo.",
  "지고 있을 때 기물을 바꾸면 역전 기회도 함께 줄어들습니다. 이 교환은 아쉬운 선택이었습니다.": "Cambiar Piezas cuando vas por detrás también reduce las opciones de remontar, este cambio fue una pena.",
  "역전을 노려야 할 때 목적 없이 기물을 교환한 건 아쉬운 선택입니다.": "Cambiar Piezas sin propósito cuando hay que buscar la remontada es una pena.",
