  "정한 수까지의 오프닝을 도감에서 무작위로 뽑음": "Elige al azar una apertura de la longitud elegida del catálogo de aperturas",
  "정한 수까지의 오프닝을 도감에서 뽑는 룰렛 전송 (수를 비우면 고르는 창)": "Envía una ruleta que elige una apertura de esa longitud del catálogo de aperturas (sin número se abre el selector)",
  "최선의 수 퀴즈": "Quiz de la mejor jugada",
