  "장의 퀘스트를 모두 클리어하면 더 어려운 다음 장이 열림. 일반 대국은 10수(양쪽 합 20수) 이상 두고 끝내야 인정됨": "Completa todas las misiones de un capítulo para desbloquear el siguiente, más difícil. Las partidas normales cuentan solo si duran 10 jugadas (20 medias jugadas) o más",
